{
  "name": "opencode-durable-goal",
  "version": "0.1.2",
  "description": "Codex-inspired persistent goals for OpenCode with lightweight continuation and agent-judged stall/block decisions.",
  "type": "module",
  "main": "src/index.ts",
  "exports": {
    ".": "./src/index.ts"
  },
  "files": [
    "src/",
    "README.md",
    "LICENSE"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "goal",
    "durable-goal",
    "persistent-goal",
    "agent"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/huaruoji/opencode-durable-goal.git"
  },
  "homepage": "https://github.com/huaruoji/opencode-durable-goal#readme",
  "bugs": {
    "url": "https://github.com/huaruoji/opencode-durable-goal/issues"
  },
  "publishConfig": {
    "access": "public",
    "registry": "https://registry.npmjs.org/"
  },
  "dependencies": {
    "@opencode-ai/plugin": "1.15.13"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.15.13"
  }
}

import { existsSync, mkdirSync, readFileSync, unlinkSync, writeFileSync } from "fs"
import { dirname, join } from "path"
import { type Plugin, tool } from "@opencode-ai/plugin"

type GoalStatus = "active" | "complete" | "blocked"
type CriterionStatus = "pending" | "done" | "blocked"

interface GoalCriterion {
  text: string
  status: CriterionStatus
}

interface GoalNote {
  at: string
  kind: "create" | "progress" | "stalled" | "blocked" | "complete" | "clear"
  text: string
}

interface GoalState {
  id: string
  objective: string
  status: GoalStatus
  createdAt: string
  updatedAt: string
  tokenBudget?: number
  sessionId?: string
  idleContinuations: number
  maxIdleContinuations: number
  completionCriteria: GoalCriterion[]
  notes: GoalNote[]
  blockedReason?: string
}

const GOAL_DIR = ".opencode"
const GOAL_FILE = "goal.json"

function goalPath(directory: string): string {
  return join(directory, GOAL_DIR, GOAL_FILE)
}

function now(): string {
  return new Date().toISOString()
}

function safeParseGoal(content: string): GoalState | null {
  try {
    const parsed = JSON.parse(content) as GoalState & { completionCriteria?: Array<string | GoalCriterion> }
    const criteria = (parsed.completionCriteria ?? []).map((item) =>
      typeof item === "string" ? { text: item, status: "pending" as CriterionStatus } : item
    )
    return {
      ...parsed,
      idleContinuations: parsed.idleContinuations ?? 0,
      maxIdleContinuations: parsed.maxIdleContinuations ?? 8,
      completionCriteria: criteria,
    }
  } catch {
    return null
  }
}

function readGoal(directory: string): GoalState | null {
  const path = goalPath(directory)
  if (!existsSync(path)) return null
  return safeParseGoal(readFileSync(path, "utf-8"))
}

function writeGoal(directory: string, goal: GoalState): void {
  const path = goalPath(directory)
  mkdirSync(dirname(path), { recursive: true })
  writeFileSync(path, JSON.stringify(goal, null, 2) + "\n")
}

function clearGoal(directory: string): void {
  const path = goalPath(directory)
  if (existsSync(path)) unlinkSync(path)
}

function newGoalId(): string {
  return `goal_${Date.now().toString(36)}`
}

function appendNote(goal: GoalState, kind: GoalNote["kind"], text: string): GoalState {
  return {
    ...goal,
    updatedAt: now(),
    notes: [...goal.notes, { at: now(), kind, text }],
  }
}

function summarizeGoal(goal: GoalState): string {
  const criteria =
    goal.completionCriteria.length > 0
      ? goal.completionCriteria.map((item, index) => `${index + 1}. [${item.status}] ${item.text}`).join("\n")
      : "None"

  const recentNotes =
    goal.notes.length > 0
      ? goal.notes
          .slice(-5)
          .map((note) => `- [${note.kind}] ${note.text}`)
          .join("\n")
      : "None"

  return [
    `Goal ID: ${goal.id}`,
    `Objective: ${goal.objective}`,
    `Status: ${goal.status}`,
    `Created: ${goal.createdAt}`,
    `Updated: ${goal.updatedAt}`,
    `Token budget: ${goal.tokenBudget ?? "None"}`,
    `Idle continuations: ${goal.idleContinuations}/${goal.maxIdleContinuations}`,
    `Blocked reason: ${goal.blockedReason ?? "None"}`,
    "Completion criteria:",
    criteria,
    "Recent notes:",
    recentNotes,
  ].join("\n")
}

function ensureNoActiveGoal(goal: GoalState | null): string | null {
  if (goal && goal.status === "active") {
    return `An active goal already exists.\n\n${summarizeGoal(goal)}`
  }
  return null
}

function normalizeCriteria(items: string[]): GoalCriterion[] {
  return items.map((text) => ({ text, status: "pending" }))
}

function pendingCriteria(goal: GoalState): GoalCriterion[] {
  return goal.completionCriteria.filter((item) => item.status !== "done")
}

function markAllCriteriaDone(goal: GoalState): GoalCriterion[] {
  return goal.completionCriteria.map((item) => ({ ...item, status: "done" }))
}

export const DurableGoalPlugin: Plugin = async ({ directory, client }) => {
  // Track when user last aborted via ESC (cooldown window)
  let lastAbortAt: number | undefined

  return {
    tool: {
      goal_create: tool({
        description:
          "Create a durable goal for the current project. Include a short completion checklist or subgoal list that defines done. Fails if an active goal already exists. IMPORTANT: Before calling this, present the objective and completion criteria to the user for confirmation. Only create after the user explicitly agrees.",
        args: {
          objective: tool.schema.string().describe("The concrete durable objective to pursue"),
          completionCriteria: tool.schema.array(tool.schema.string()).default([]).describe("Checklist items that define done"),
          tokenBudget: tool.schema.number().optional().describe("Optional token budget for the goal"),
          maxIdleContinuations: tool.schema.number().default(8).describe("Maximum automatic continuations after idle"),
        },
        async execute({ objective, completionCriteria = [], tokenBudget, maxIdleContinuations = 8 }) {
          const existing = readGoal(directory)
          const conflict = ensureNoActiveGoal(existing)
          if (conflict) return conflict

          const createdAt = now()
          const goal: GoalState = {
            id: newGoalId(),
            objective,
            status: "active",
            createdAt,
            updatedAt: createdAt,
            tokenBudget,
            idleContinuations: 0,
            maxIdleContinuations,
            completionCriteria: normalizeCriteria(completionCriteria),
            notes: [
              {
                at: createdAt,
                kind: "create",
                text: objective,
              },
            ],
          }
          writeGoal(directory, goal)
          return `Goal created.\n\n${summarizeGoal(goal)}\n\nIf this goal does not match your expectations, use goal_clear to remove it and start over.`
        },
      }),

      goal_get: tool({
        description: "Get the current durable goal for the project.",
        args: {},
        async execute() {
          const goal = readGoal(directory)
          if (!goal) return "No goal exists for this project."
          return summarizeGoal(goal)
        },
      }),

      goal_note: tool({
        description: "Append a progress note to the current goal without changing its status.",
        args: {
          note: tool.schema.string().describe("Concrete progress update"),
        },
        async execute({ note }) {
          const goal = readGoal(directory)
          if (!goal) return "No goal exists for this project."
          const updated = appendNote(
            {
              ...goal,
              blockedReason: undefined,
              idleContinuations: 0,
            },
            "progress",
            note
          )
          writeGoal(directory, updated)
          return `Progress recorded.\n\n${summarizeGoal(updated)}`
        },
      }),

      goal_complete: tool({
        description:
          "Mark the current durable goal complete with a completion summary. Before calling this, the agent should verify each completion criterion has been satisfied.",
        args: {
          summary: tool.schema.string().describe("Why the goal is complete"),
        },
        async execute({ summary }) {
          const goal = readGoal(directory)
          if (!goal) return "No goal exists for this project."
          const updated = appendNote(
            {
              ...goal,
              status: "complete",
              blockedReason: undefined,
              idleContinuations: 0,
              completionCriteria: markAllCriteriaDone(goal),
            },
            "complete",
            summary
          )
          writeGoal(directory, updated)
          return `Goal marked complete.\n\n${summarizeGoal(updated)}`
        },
      }),

      goal_blocked: tool({
        description:
          "Mark the current goal blocked. Use only when the agent judges the goal cannot continue under current conditions.",
        args: {
          reason: tool.schema.string().describe("The concrete blocking condition"),
        },
        async execute({ reason }) {
          const goal = readGoal(directory)
          if (!goal) return "No goal exists for this project."
          const updated = appendNote(
            {
              ...goal,
              status: "blocked",
              blockedReason: reason,
              idleContinuations: 0,
            },
            "blocked",
            reason
          )
          writeGoal(directory, updated)
          return `Goal marked blocked.\n\n${summarizeGoal(updated)}`
        },
      }),

      goal_stall: tool({
        description:
          "Record that the agent stalled or stopped early, but the goal should remain active and continue with another approach.",
        args: {
          reason: tool.schema.string().describe("Why this is a stall rather than a true block"),
          nextAttempt: tool.schema.string().optional().describe("Optional concrete next approach to try"),
        },
        async execute({ reason, nextAttempt }) {
          const goal = readGoal(directory)
          if (!goal) return "No goal exists for this project."
          const detail = nextAttempt ? `${reason} Next attempt: ${nextAttempt}` : reason
          const updated = appendNote(
            {
              ...goal,
              status: "active",
              blockedReason: undefined,
            },
            "stalled",
            detail
          )
          writeGoal(directory, updated)
          return `Stall recorded; goal remains active.\n\n${summarizeGoal(updated)}`
        },
      }),

      goal_clear: tool({
        description: "Clear the current goal file. Use only when resetting goal state intentionally.",
        args: {
          reason: tool.schema.string().optional().describe("Why the goal is being cleared"),
        },
        async execute({ reason }) {
          const goal = readGoal(directory)
          if (!goal) return "No goal exists for this project."
          const updated = appendNote(goal, "clear", reason || "manual reset")
          writeGoal(directory, updated)
          clearGoal(directory)
          return `Goal cleared.\n\nLast state before clearing:\n${summarizeGoal(updated)}`
        },
      }),

      goal_resume: tool({
        description: "Resume a blocked or completed goal by setting it back to active.",
        args: {
          reason: tool.schema.string().describe("Why the goal is being resumed"),
        },
        async execute({ reason }) {
          const goal = readGoal(directory)
          if (!goal) return "No goal exists for this project."
          const updated = appendNote(
            {
              ...goal,
              status: "active",
              blockedReason: undefined,
              idleContinuations: 0,
            },
            "progress",
            `Goal resumed: ${reason}`
          )
          writeGoal(directory, updated)
          return `Goal resumed.\n\n${summarizeGoal(updated)}`
        },
      }),
    },

    event: async ({ event }) => {
      // Detect user abort (ESC) — skip continuation within cooldown window
      if (event.type === "session.error") {
        const err = (event as any).properties?.error
        if (err && (err.name === "MessageAbortedError" || err.name === "AbortError")) {
          lastAbortAt = Date.now()
        }
        return
      }

      if (event.type === "session.created") {
        const goal = readGoal(directory)
        if (!goal || goal.status !== "active") return

        const sessionId = event.properties?.sessionID
        if (!sessionId) return

        const nextGoal = {
          ...goal,
          sessionId,
          updatedAt: now(),
        }
        writeGoal(directory, nextGoal)
        return
      }

      if (event.type !== "session.idle") return

      // Don't auto-continue if user recently cancelled via ESC
      if (lastAbortAt && Date.now() - lastAbortAt < 30_000) return

      const goal = readGoal(directory)
      if (!goal || goal.status !== "active") return

      const sessionId = event.properties?.sessionID
      if (!sessionId) return
      if (goal.sessionId && goal.sessionId !== sessionId) return
      if (goal.idleContinuations >= goal.maxIdleContinuations) return

      const nextGoal = {
        ...goal,
        sessionId,
        idleContinuations: goal.idleContinuations + 1,
        updatedAt: now(),
      }
      writeGoal(directory, nextGoal)

      const criteria =
        pendingCriteria(goal).length > 0
          ? pendingCriteria(goal).map((item, index) => `${index + 1}. [${item.status}] ${item.text}`).join("\n")
          : "All checklist items are already marked done."

      const reminder = [
        `[GOAL CONTINUATION ${nextGoal.idleContinuations}/${nextGoal.maxIdleContinuations}]`,
        `Goal: ${goal.objective}`,
        "",
        "The goal is still active. You likely stopped early or stalled. Continue the work and prefer trying a different approach before giving up.",
        "Judge the situation yourself:",
        "- If the objective is truly finished, call `goal_complete` with a concise summary.",
        "- If you merely stalled or need a different tactic, call `goal_stall` and then continue with the next attempt.",
        "- Only call `goal_blocked` if the goal cannot continue under current conditions.",
        "- If you made progress, call `goal_note` before moving on.",
        "",
        "Before calling `goal_complete`, explicitly verify the completion criteria one by one in your own reasoning.",
        "Before deciding the goal is blocked, prefer to try another concrete method, command, or debugging route.",
        "",
        "Completion criteria:",
        criteria,
      ].join("\n")

      try {
        await client.session.prompt({
          path: { id: sessionId },
          body: {
            parts: [{ type: "text", text: reminder }],
          },
        })
      } catch {}
    },
  }
}

export default DurableGoalPlugin
